package payment

import (
	"encoding/json"
	"html"
	"net/url"
	"regexp"
	"sort"
	"strings"
	"time"
)

var alipayCheckoutInput = regexp.MustCompile(`^<input type="hidden" name="([a-zA-Z0-9_]+)" value="([^"]*)">`)

// PrepareCheckoutHTML verifies only the exact page/wap form generated by this
// adapter, bound to this app, gateway and order. For the old persisted form it
// changes only the form opening tag; all signed input bytes remain unchanged.
// It performs no provider I/O and does not modify the persisted attempt.
func (a *Alipay) PrepareCheckoutHTML(material, tradeNo string) (string, error) {
	if a == nil || a.config.PrivateKey == nil || tradeNo == "" || len(material) > 1<<20 {
		return "", ErrInvalid
	}
	oldPrefix := `<form method="post" action="` + html.EscapeString(a.config.GatewayURL) + `">`
	gateway := a.config.GatewayURL + "?" + (url.Values{"charset": {"utf-8"}}).Encode()
	newPrefix := `<form method="post" accept-charset="UTF-8" action="` + html.EscapeString(gateway) + `">`
	tail := ""
	switch {
	case strings.HasPrefix(material, oldPrefix):
		tail = strings.TrimPrefix(material, oldPrefix)
	case strings.HasPrefix(material, newPrefix):
		tail = strings.TrimPrefix(material, newPrefix)
	default:
		return "", ErrAuthentication
	}
	const suffix = `<button type="submit">支付宝支付</button></form>`
	if !strings.HasSuffix(tail, suffix) {
		return "", ErrAuthentication
	}
	inputs := strings.TrimSuffix(tail, suffix)
	params := make(map[string]string)
	last := ""
	for inputs != "" {
		match := alipayCheckoutInput.FindStringSubmatch(inputs)
		if len(match) != 3 {
			return "", ErrAuthentication
		}
		key, value := match[1], html.UnescapeString(match[2])
		if key <= last || html.EscapeString(value) != match[2] {
			return "", ErrAuthentication
		}
		last, params[key] = key, value
		inputs = strings.TrimPrefix(inputs, match[0])
	}
	if params["app_id"] != a.config.AppID || params["charset"] != "utf-8" || params["sign_type"] != "RSA2" || (params["method"] != "alipay.trade.page.pay" && params["method"] != "alipay.trade.wap.pay") {
		return "", ErrAuthentication
	}
	var biz struct {
		OutTradeNo string `json:"out_trade_no"`
	}
	if json.Unmarshal([]byte(params["biz_content"]), &biz) != nil || biz.OutTradeNo != tradeNo || !verifyRSA([]byte(AlipayRequestCanonical(params)), params["sign"], &a.config.PrivateKey.PublicKey) {
		return "", ErrAuthentication
	}
	return newPrefix + tail, nil
}

// RefreshCheckoutHTML verifies the original stored form before producing an
// in-memory replacement. Only the timestamp and caller-issued return URL are
// changed before RSA2 re-signing. It never calls the provider or writes data.
func (a *Alipay) RefreshCheckoutHTML(material, tradeNo, returnURL string) (string, error) {
	if len(returnURL) > 8192 || !validPaymentURL(returnURL) {
		return "", ErrInvalid
	}
	verified, err := a.PrepareCheckoutHTML(material, tradeNo)
	if err != nil {
		return "", err
	}
	gateway := a.config.GatewayURL + "?" + (url.Values{"charset": {"utf-8"}}).Encode()
	prefix := `<form method="post" accept-charset="UTF-8" action="` + html.EscapeString(gateway) + `">`
	const suffix = `<button type="submit">支付宝支付</button></form>`
	inputs := strings.TrimSuffix(strings.TrimPrefix(verified, prefix), suffix)
	params := make(map[string]string)
	for inputs != "" {
		match := alipayCheckoutInput.FindStringSubmatch(inputs)
		if len(match) != 3 {
			return "", ErrAuthentication
		}
		params[match[1]] = html.UnescapeString(match[2])
		inputs = strings.TrimPrefix(inputs, match[0])
	}
	params["return_url"] = returnURL
	params["timestamp"] = a.config.Now().In(time.FixedZone("Asia/Shanghai", 8*3600)).Format("2006-01-02 15:04:05")
	params["sign"], err = SignAlipayRSA2(params, a.config.PrivateKey)
	if err != nil {
		return "", err
	}
	keys := make([]string, 0, len(params))
	for key := range params {
		keys = append(keys, key)
	}
	sort.Strings(keys)
	var b strings.Builder
	b.WriteString(prefix)
	for _, key := range keys {
		b.WriteString(`<input type="hidden" name="` + html.EscapeString(key) + `" value="` + html.EscapeString(params[key]) + `">`)
	}
	b.WriteString(suffix)
	return b.String(), nil
}
